import{_ as e,o as a,c as d,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const L=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/RELIABILITY.md","filePath":"manual-zh/RELIABILITY.md","lastUpdated":1785684581000}'),r={name:"manual-zh/RELIABILITY.md"};function c(n,t,p,s,l,i){return a(),d("div",null,[...t[0]||(t[0]=[o(`<h3 id="_15-18-reliability" tabindex="-1">15.18 RELIABILITY <a class="header-anchor" href="#_15-18-reliability" aria-label="Permalink to &quot;15.18 RELIABILITY&quot;">​</a></h3><pre><code>RELIABILITY
        /VARIABLES=var_list
        /SCALE (name) = {var_list, ALL}
        /MODEL={ALPHA, SPLIT[(n)]}
        /SUMMARY={TOTAL,ALL}
        /MISSING={EXCLUDE,INCLUDE}
</code></pre><p><code>RELIABILITY</code> 命令对数据进行信度分析。</p><p><code>VARIABLES</code> 子命令是必需的。它确定要执行分析所基于的变量集合。</p><p><code>SCALE</code> 子命令确定要计算信度的变量。如果省略 <code>SCALE</code>，则使用 <code>VARIABLES</code> 子命令中命名的所有变量进行分析。可选的参数 name 可用来为量表设置一个字符串名称。</p><p><code>MODEL</code> 子命令确定分析的类型。如果指定 <code>ALPHA</code>，则计算该量表的 Cronbach’s Alpha（克隆巴赫 alpha 系数）。如果模型为 <code>SPLIT</code>，则变量被分为 2 个子集。可给出可选参数 n，以指定第一个子集中包含多少个变量。如果省略 n，则默认为量表中变量数的一半；若变量数为奇数，则为一半减一。默认模型是 <code>ALPHA</code>。</p><p>默认情况下，在 <code>VARIABLES</code> 子命令中给出的任意变量含有用户缺失值或系统缺失值的个案，都会被从分析中剔除。<code>MISSING</code> 子命令决定用户缺失值是纳入还是排除在分析之外。</p><p><code>SUMMARY</code> 子命令确定要执行的汇总分析类型。目前只有一种类型：<code>SUMMARY=TOTAL</code>，它显示针对合计值进行检验的逐题项分析。</p><h4 id="_15-18-1-示例-可靠性" tabindex="-1">15.18.1 示例 - 可靠性 <a class="header-anchor" href="#_15-18-1-示例-可靠性" aria-label="Permalink to &quot;15.18.1 示例 - 可靠性&quot;">​</a></h4><p>在分析一项调查的结果之前——尤其是对于选择题调查——最好先了解受访者是认真考虑了答案，还是仅仅随意作答。</p><p>在下面的例子中，使用了文件 hotel.sav 中的调查结果。全部五道调查问题都纳入了信度分析。不过，在运行分析之前，必须对数据进行预处理。对调查问题的检查发现，v3 和 v5 两道题表述为负向，而其他题目为正向。为使分析有意义，所有问题必须基于同一量表。可以使用 <code>RECODE</code> 命令（参见 <a href="./RECODE">RECODE</a>），但更简单的做法是使用 <code>COMPUTE</code>（参见 <a href="./COMPUTE">COMPUTE</a>），示例 15.8 中采用的就是这种方法。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get file=&quot;hotel.sav&quot;.  * Recode V3 and V5 inverting the sense of the values. compute v3 = 6 - v3. compute v5 = 6 - v5.  reliability 	/variables= all 	/model=alpha.</span></span></code></pre></div><p><strong>示例 15.8：</strong> 调查应答信度调查</p><p>本例中使用了数据集中的所有变量。因此可以使用特殊关键字 ‘ALL’（参见 <a href="./BNF">BNF</a>）。</p><p><strong>截图 15.8：</strong> 选中全部变量的可靠性对话框</p><p>结果 15.6 显示 Cronbach’s Alpha 为 0.11，这一数值通常被认为过低，不足以表明数据内部的一致性。这可能源于调查问题数量较少。在认真使用其结果之前，应重新设计该项调查。</p><table tabindex="0"><thead><tr><th>个案</th><th>N</th><th>百分比</th></tr></thead><tbody><tr><td>有效</td><td>17</td><td>100.0%</td></tr><tr><td>排除</td><td>0</td><td>.0%</td></tr><tr><td>合计</td><td>17</td><td>100.0%</td></tr><tr><td>Cronbach&#39;s Alpha</td><td>项目数 N</td><td></td></tr><tr><td>.11</td><td>5</td><td></td></tr></tbody></table><p><strong>结果 15.6：</strong> 对 hotel.sav 执行可靠性命令的结果</p>`,18)])])}const A=e(r,[["render",c]]);export{L as __pageData,A as default};
